package com.qrid.servlet;
import com.qrid.config.Database;import com.qrid.dao.AuditDao;import com.qrid.model.User;import com.qrid.util.*;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;import java.sql.*;
@WebServlet("/profile") public class ProfileServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/common/profile.jsp").forward(r,s);}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{User u=(User)r.getSession().getAttribute("user");String old=r.getParameter("currentPassword"),n=r.getParameter("newPassword"),confirm=r.getParameter("confirmPassword");try{String hash=null;try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT password_hash FROM users WHERE id=?")){p.setLong(1,u.getId());try(ResultSet rs=p.executeQuery()){if(rs.next())hash=rs.getString(1);}}if(!PasswordUtil.matches(old,hash))throw new IllegalArgumentException("Current password is incorrect.");if(n==null||n.length()<8||!n.equals(confirm))throw new IllegalArgumentException("New passwords must match and contain at least 8 characters.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE users SET password_hash=? WHERE id=?")){p.setString(1,PasswordUtil.hash(n));p.setLong(2,u.getId());p.executeUpdate();}new AuditDao().log(u.getId(),"PASSWORD_CHANGED","USER",String.valueOf(u.getId()),"Password updated",r.getRemoteAddr());Flash.set(r,"success","Password changed successfully.");}catch(Exception e){Flash.set(r,"danger",e.getMessage());}s.sendRedirect(r.getContextPath()+"/profile");}
}
